//! Library → CLI sync. Each CLI has a writer producing whole generated files
//! and sections for shared files (`AGENTS.md`, `CLAUDE.md`, …). Shared files
//! are only edited between managed markers; generated files are tracked in
//! `.orchestrator/managed.json` and never overwritten after a user edit.
//! Sync is incremental: unchanged content is not rewritten.
//!
//! Native locations verified at build time are listed in docs/DECISIONS.md.

use super::{join_frontmatter, Item, Kind};
use crate::brand;
use anyhow::Result;
use serde::{Deserialize, Serialize};
use serde_yaml::{Mapping, Value};
use sha2::{Digest, Sha256};
use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

pub const CLIS: &[&str] = &["claude", "cursor", "codex", "copilot", "opencode", "aider", "goose"];

#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum Support {
    Native,
    /// Converted into another native form (e.g. a Cursor rule for an agent).
    Converted,
    /// Injected into the step's task file instead.
    Fallback,
}

pub fn support(cli: &str, kind: Kind) -> Support {
    use Kind::*;
    use Support::*;
    match (cli, kind) {
        ("claude", _) => Native,
        ("opencode", _) => Native,
        ("cursor", Rule) => Native,
        ("cursor", Agent) => Converted,
        ("copilot", Rule) | ("copilot", Agent) => Native,
        ("codex", Rule) | ("aider", Rule) | ("goose", Rule) => Native,
        _ => Fallback,
    }
}

fn marker_name() -> String {
    brand::SHORT_NAME.to_ascii_lowercase().replace(' ', "-")
}

pub fn begin_marker(comment: &str) -> String {
    if comment == "#" {
        format!("# {}:begin", marker_name())
    } else {
        format!("<!-- {}:begin -->", marker_name())
    }
}

pub fn end_marker(comment: &str) -> String {
    if comment == "#" {
        format!("# {}:end", marker_name())
    } else {
        format!("<!-- {}:end -->", marker_name())
    }
}

/// Replaces (or appends/removes) the managed block in `content`. Everything
/// outside the markers is left byte-for-byte untouched.
pub fn replace_block(content: &str, block: &str, comment: &str) -> String {
    let (b, e) = (begin_marker(comment), end_marker(comment));
    let new_block = if block.trim().is_empty() { String::new() } else { format!("{b}\n{}\n{e}\n", block.trim_end()) };
    if let (Some(i), Some(j)) = (content.find(&b), content.find(&e)) {
        if j > i {
            let mut end = j + e.len();
            if content[end..].starts_with('\n') {
                end += 1;
            }
            let mut out = String::with_capacity(content.len() + new_block.len());
            out.push_str(&content[..i]);
            out.push_str(&new_block);
            out.push_str(&content[end..]);
            if new_block.is_empty() {
                return out.trim_end_matches('\n').to_string() + if out.trim().is_empty() { "" } else { "\n" };
            }
            return out;
        }
    }
    if new_block.is_empty() {
        return content.to_string();
    }
    if content.is_empty() {
        return new_block;
    }
    let sep = if content.ends_with("\n\n") {
        ""
    } else if content.ends_with('\n') {
        "\n"
    } else {
        "\n\n"
    };
    format!("{content}{sep}{new_block}")
}

/// The text outside any managed block (what the user wrote).
pub fn outside_block(content: &str) -> String {
    let (b, e) = (begin_marker("<!--"), end_marker("<!--"));
    match (content.find(&b), content.find(&e)) {
        (Some(i), Some(j)) if j > i => format!("{}{}", &content[..i], &content[j + e.len()..]).trim().to_string(),
        _ => content.trim().to_string(),
    }
}

fn gen_note() -> String {
    format!("<!-- Generated by {}. Edit it in the Library; direct edits here are detected and can be imported. -->", brand::PRODUCT_NAME)
}

fn with_frontmatter(pairs: Vec<(&str, Value)>, body: &str) -> String {
    let mut m = Mapping::new();
    for (k, v) in pairs {
        if !matches!(v, Value::Null) {
            m.insert(k.into(), v);
        }
    }
    let body = format!("{}\n\n{}", gen_note(), body.trim());
    let mut s = join_frontmatter(&m, &body);
    if !s.ends_with('\n') {
        s.push('\n');
    }
    s
}

fn seq(v: &[String]) -> Value {
    if v.is_empty() {
        Value::Null
    } else {
        Value::Sequence(v.iter().map(|s| Value::String(s.clone())).collect())
    }
}

fn opt(v: &Option<String>) -> Value {
    v.as_ref().map(|s| Value::String(s.clone())).unwrap_or(Value::Null)
}

/// Rules rendered as a markdown section for shared instruction files.
fn rules_section(rules: &[&Item]) -> String {
    if rules.is_empty() {
        return String::new();
    }
    let mut s = format!("## Rules from the {} Library\n\n", brand::PRODUCT_NAME);
    for r in rules {
        s.push_str(&format!("### {}\n", r.display_name));
        if !r.applies_to.is_empty() && !r.always_on {
            s.push_str(&format!("_Applies to: {}_\n\n", r.applies_to.join(", ")));
        }
        s.push_str(r.body.trim());
        s.push_str("\n\n");
    }
    s
}

/// SKILL.md in Agent Skills format: only `name` and `description` in frontmatter.
fn skill_md(i: &Item) -> String {
    with_frontmatter(vec![("name", Value::String(i.id.clone())), ("description", Value::String(i.description.clone()))], &i.body)
}

#[derive(Default, Debug, Clone)]
pub struct SyncPlan {
    /// Whole generated files: relative path → content.
    pub files: BTreeMap<String, String>,
    /// Supporting files copied verbatim (skill resources): relative path → source path.
    pub copies: BTreeMap<String, PathBuf>,
    /// Shared files: relative path → managed block content.
    pub blocks: BTreeMap<String, String>,
}

/// Builds the sync plan for the installed CLIs.
pub fn plan(items: &[Item], clis: &[&str]) -> SyncPlan {
    let rules: Vec<&Item> = items.iter().filter(|i| i.kind == Kind::Rule).collect();
    let always_rules: Vec<&Item> = rules.iter().copied().filter(|r| r.always_on || r.applies_to.is_empty()).collect();
    let skills: Vec<&Item> = items.iter().filter(|i| i.kind == Kind::Skill).collect();
    let agents: Vec<&Item> = items.iter().filter(|i| i.kind == Kind::Agent).collect();
    let mut p = SyncPlan::default();
    let has = |c: &str| clis.contains(&c);
    let add_skill = |p: &mut SyncPlan, base: &str, s: &Item| {
        p.files.insert(format!("{base}/{}/SKILL.md", s.id), skill_md(s));
        if let Some(dir) = s.skill_dir() {
            for (rel, src) in skill_resources(&dir) {
                p.copies.insert(format!("{base}/{}/{rel}", s.id), src);
            }
        }
    };

    // Shared AGENTS.md block serves Codex, OpenCode, Aider (via --read) and Goose.
    if has("codex") || has("opencode") || has("aider") || has("goose") {
        p.blocks.insert("AGENTS.md".into(), rules_section(&rules));
    }
    if has("claude") {
        p.blocks.insert("CLAUDE.md".into(), rules_section(&rules));
        for s in &skills {
            add_skill(&mut p, ".claude/skills", s);
        }
        for a in &agents {
            let tools = if a.tools.is_empty() { Value::Null } else { Value::String(a.tools.join(", ")) };
            let model =
                a.model.as_ref().filter(|m| ["sonnet", "opus", "haiku", "inherit"].contains(&m.as_str()) || m.starts_with("claude-"));
            p.files.insert(
                format!(".claude/agents/{}.md", a.id),
                with_frontmatter(
                    vec![
                        ("name", Value::String(a.id.clone())),
                        ("description", Value::String(a.description.clone())),
                        ("tools", tools),
                        ("model", opt(&model.cloned())),
                    ],
                    &agent_body(a, items),
                ),
            );
        }
    }
    if has("cursor") {
        for r in &rules {
            let globs = if r.applies_to.is_empty() { Value::Null } else { Value::String(r.applies_to.join(",")) };
            p.files.insert(
                format!(".cursor/rules/{}.mdc", r.id),
                with_frontmatter(
                    vec![
                        (
                            "description",
                            Value::String(if r.description.is_empty() { r.display_name.clone() } else { r.description.clone() }),
                        ),
                        ("globs", globs),
                        ("alwaysApply", Value::Bool(r.always_on)),
                    ],
                    &r.body,
                ),
            );
        }
        for a in &agents {
            p.files.insert(
                format!(".cursor/rules/agent-{}.mdc", a.id),
                with_frontmatter(
                    vec![
                        ("description", Value::String(format!("Role \"{}\": {}", a.display_name, a.description))),
                        ("alwaysApply", Value::Bool(false)),
                    ],
                    &agent_body(a, items),
                ),
            );
        }
    }
    if has("copilot") {
        p.blocks.insert(".github/copilot-instructions.md".into(), rules_section(&rules));
        for a in &agents {
            p.files.insert(
                format!(".github/agents/{}.agent.md", a.id),
                with_frontmatter(
                    vec![
                        ("name", Value::String(a.id.clone())),
                        ("description", Value::String(a.description.clone())),
                        ("tools", seq(&a.tools)),
                    ],
                    &agent_body(a, items),
                ),
            );
        }
    }
    if has("opencode") {
        for s in &skills {
            add_skill(&mut p, ".opencode/skills", s);
        }
        for a in &agents {
            p.files.insert(
                format!(".opencode/agents/{}.md", a.id),
                with_frontmatter(
                    vec![("description", Value::String(a.description.clone())), ("mode", Value::String("all".into()))],
                    &agent_body(a, items),
                ),
            );
        }
    }
    if has("goose") {
        p.blocks.insert(".goosehints".into(), rules_section(&always_rules));
    }
    // Fallback copies of skills for CLIs without a native skills folder; task
    // files point at these (inside the git-ignored handoff dir).
    if clis.iter().any(|c| support(c, Kind::Skill) == Support::Fallback) {
        for s in &skills {
            add_skill(&mut p, &format!("{}/skills", brand::HANDOFF_DIR_NAME), s);
        }
    }
    p
}

/// A Library agent's prompt with its attached rules appended.
pub fn agent_body(a: &Item, items: &[Item]) -> String {
    let mut s = a.body.trim().to_string();
    let rules: Vec<&Item> = items.iter().filter(|i| i.kind == Kind::Rule && a.rules.contains(&i.id)).collect();
    if !rules.is_empty() {
        s.push_str("\n\n## Rules\n");
        for r in rules {
            s.push_str(&format!("- **{}**: {}\n", r.display_name, r.body.trim().replace('\n', " ")));
        }
    }
    if !a.skills.is_empty() {
        s.push_str(&format!("\n\nSkills to use when relevant: {}.\n", a.skills.join(", ")));
    }
    s
}

fn skill_resources(dir: &Path) -> Vec<(String, PathBuf)> {
    let mut out = vec![];
    fn walk(base: &Path, d: &Path, out: &mut Vec<(String, PathBuf)>) {
        let Ok(rd) = std::fs::read_dir(d) else { return };
        for e in rd.flatten() {
            let p = e.path();
            if p.is_dir() {
                walk(base, &p, out);
            } else if p.file_name().is_some_and(|n| n != "SKILL.md") {
                out.push((p.strip_prefix(base).unwrap().to_string_lossy().replace('\\', "/"), p));
            }
        }
    }
    walk(dir, dir, &mut out);
    out
}

#[derive(Serialize, Deserialize, Default, Debug, Clone)]
pub struct Managed {
    #[serde(default)]
    pub files: BTreeMap<String, String>,
    #[serde(default)]
    pub blocks: BTreeMap<String, String>,
}

pub fn managed_path(ws: &Path) -> PathBuf {
    crate::handoff::dir(ws).join("managed.json")
}

pub fn load_managed(ws: &Path) -> Managed {
    std::fs::read(managed_path(ws)).ok().and_then(|b| serde_json::from_slice(&b).ok()).unwrap_or_default()
}

pub fn hash(s: &[u8]) -> String {
    hex::encode(Sha256::digest(s))[..16].to_string()
}

#[derive(Serialize, Debug, Clone, PartialEq)]
pub struct Conflict {
    pub path: String,
    /// "edited" (user changed a generated file) or "exists" (a file we didn't create).
    pub reason: String,
}

#[derive(Serialize, Debug, Clone, Default)]
pub struct SyncReport {
    pub written: Vec<String>,
    pub removed: Vec<String>,
    pub unchanged: usize,
    pub conflicts: Vec<Conflict>,
    /// cli → kind → support.
    pub status: BTreeMap<String, BTreeMap<String, Support>>,
}

/// Applies a plan to the workspace. `commit_generated` = don't git-ignore generated files.
pub fn apply(ws: &Path, plan: &SyncPlan, clis: &[&str], commit_generated: bool) -> Result<SyncReport> {
    crate::handoff::ensure(ws)?;
    let mut managed = load_managed(ws);
    let mut report = SyncReport::default();
    let mut desired: BTreeSet<String> = BTreeSet::new();

    let mut write_whole = |rel: &str, bytes: &[u8], managed: &mut Managed, report: &mut SyncReport| -> Result<()> {
        desired.insert(rel.to_string());
        let dst = ws.join(rel);
        let new_hash = hash(bytes);
        if let Ok(cur) = std::fs::read(&dst) {
            let cur_hash = hash(&cur);
            if cur_hash == new_hash {
                managed.files.insert(rel.to_string(), new_hash);
                report.unchanged += 1;
                return Ok(());
            }
            match managed.files.get(rel) {
                None => {
                    report.conflicts.push(Conflict { path: rel.into(), reason: "exists".into() });
                    return Ok(());
                }
                Some(recorded) if *recorded != cur_hash => {
                    report.conflicts.push(Conflict { path: rel.into(), reason: "edited".into() });
                    return Ok(());
                }
                _ => {}
            }
        }
        if let Some(p) = dst.parent() {
            std::fs::create_dir_all(p)?;
        }
        std::fs::write(&dst, bytes)?;
        managed.files.insert(rel.to_string(), new_hash);
        report.written.push(rel.to_string());
        Ok(())
    };

    for (rel, content) in &plan.files {
        write_whole(rel, content.as_bytes(), &mut managed, &mut report)?;
    }
    for (rel, src) in &plan.copies {
        if let Ok(bytes) = std::fs::read(src) {
            write_whole(rel, &bytes, &mut managed, &mut report)?;
        }
    }

    // Remove generated files that are no longer wanted (unless the user edited them).
    let stale: Vec<String> = managed.files.keys().filter(|k| !desired.contains(*k)).cloned().collect();
    for rel in stale {
        let dst = ws.join(&rel);
        match std::fs::read(&dst) {
            Ok(cur) if Some(&hash(&cur)) == managed.files.get(&rel) => {
                std::fs::remove_file(&dst)?;
                remove_empty_parents(ws, &dst);
                managed.files.remove(&rel);
                report.removed.push(rel);
            }
            Ok(_) => report.conflicts.push(Conflict { path: rel, reason: "edited".into() }),
            Err(_) => {
                managed.files.remove(&rel);
            }
        }
    }

    // Shared files: rewrite only our block. Files we used to manage but no
    // longer target get their block removed.
    let mut block_targets: BTreeMap<String, String> = plan.blocks.clone();
    for old in managed.blocks.keys() {
        block_targets.entry(old.clone()).or_default();
    }
    for (rel, block) in &block_targets {
        let dst = ws.join(rel);
        let cur = std::fs::read_to_string(&dst).unwrap_or_default();
        let next = replace_block(&cur, block, "<!--");
        if next == cur {
            report.unchanged += 1;
        } else if next.trim().is_empty() && !cur.is_empty() && outside_block(&cur).is_empty() {
            std::fs::remove_file(&dst)?;
            report.removed.push(rel.clone());
        } else if !next.trim().is_empty() {
            if let Some(p) = dst.parent() {
                std::fs::create_dir_all(p)?;
            }
            std::fs::write(&dst, &next)?;
            report.written.push(rel.clone());
        }
        if block.trim().is_empty() {
            managed.blocks.remove(rel);
        } else {
            managed.blocks.insert(rel.clone(), hash(block.as_bytes()));
        }
    }

    std::fs::write(managed_path(ws), serde_json::to_vec_pretty(&managed)?)?;

    if !commit_generated {
        let patterns: Vec<String> = managed.files.keys().map(|k| format!("/{k}")).collect();
        crate::workspace::git::set_excludes(ws, &patterns)?;
    }

    for cli in clis {
        let mut m = BTreeMap::new();
        for k in Kind::all() {
            m.insert(format!("{:?}", k).to_lowercase(), support(cli, k));
        }
        report.status.insert(cli.to_string(), m);
    }
    Ok(report)
}

fn remove_empty_parents(ws: &Path, file: &Path) {
    let mut d = file.parent();
    while let Some(dir) = d {
        if dir == ws || std::fs::remove_dir(dir).is_err() {
            break;
        }
        d = dir.parent();
    }
}

/// Preview of what each CLI receives for one item (Library screen).
pub fn preview(item: &Item, items: &[Item], cli: &str) -> (Support, String) {
    let sup = support(cli, item.kind);
    let one = [item.clone()];
    let p = plan(&one, &[cli]);
    let text = match item.kind {
        Kind::Rule => p.files.values().next().cloned().or_else(|| p.blocks.values().next().cloned()).unwrap_or_default(),
        Kind::Agent if sup != Support::Fallback => p.files.values().next().cloned().unwrap_or_default(),
        Kind::Skill if sup == Support::Native => p.files.values().next().cloned().unwrap_or_default(),
        Kind::Agent => format!("## Role\n{}", agent_body(item, items)),
        Kind::Skill => format!("## Skills available\n- **{}**: {}", item.id, item.description),
    };
    (sup, text)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::library::{create, global_root, list, Scope};

    #[test]
    fn block_replace_never_touches_user_text() {
        let user = "# My project\n\nMy own notes.\n";
        let a = replace_block(user, "rule one", "<!--");
        assert!(a.starts_with(user));
        assert!(a.contains("rule one"));
        let b = replace_block(&a, "rule two", "<!--");
        assert!(b.starts_with(user));
        assert!(!b.contains("rule one"));
        let c = replace_block(&b, "", "<!--");
        assert_eq!(c.trim_end(), user.trim_end());
        assert_eq!(outside_block(&b), user.trim());
    }

    fn setup() -> (tempfile::TempDir, tempfile::TempDir, Vec<Item>) {
        let data = tempfile::tempdir().unwrap();
        let ws = tempfile::tempdir().unwrap();
        let root = global_root(data.path());
        create(&root, Kind::Rule, Scope::Global, "Conventional commits").unwrap();
        create(&root, Kind::Skill, Scope::Global, "Write migration").unwrap();
        create(&root, Kind::Agent, Scope::Global, "Test writer").unwrap();
        let items = list(data.path(), None);
        (data, ws, items)
    }

    #[test]
    fn sync_writes_native_files_and_is_incremental() {
        let (_d, ws, items) = setup();
        let clis = ["claude", "cursor", "opencode"];
        std::fs::write(ws.path().join("AGENTS.md"), "User content\n").unwrap();
        let r = apply(ws.path(), &plan(&items, &clis), &clis, false).unwrap();
        assert!(r.conflicts.is_empty(), "{:?}", r.conflicts);
        for f in [
            ".claude/skills/write-migration/SKILL.md",
            ".claude/agents/test-writer.md",
            ".cursor/rules/conventional-commits.mdc",
            ".cursor/rules/agent-test-writer.mdc",
            ".opencode/agents/test-writer.md",
            ".opencode/skills/write-migration/SKILL.md",
            "CLAUDE.md",
        ] {
            assert!(ws.path().join(f).exists(), "{f}");
        }
        let agents = std::fs::read_to_string(ws.path().join("AGENTS.md")).unwrap();
        assert!(agents.starts_with("User content\n"));
        assert!(agents.contains("Conventional commits"));
        // Claude agent files must start with frontmatter.
        assert!(std::fs::read_to_string(ws.path().join(".claude/agents/test-writer.md")).unwrap().starts_with("---\n"));
        let r2 = apply(ws.path(), &plan(&items, &clis), &clis, false).unwrap();
        assert!(r2.written.is_empty(), "second sync rewrote {:?}", r2.written);
    }

    #[test]
    fn user_edits_are_never_clobbered() {
        let (_d, ws, items) = setup();
        let clis = ["cursor"];
        apply(ws.path(), &plan(&items, &clis), &clis, false).unwrap();
        let f = ws.path().join(".cursor/rules/conventional-commits.mdc");
        std::fs::write(&f, "my hand edit").unwrap();
        let mut items2 = items.clone();
        items2.iter_mut().for_each(|i| i.body.push_str("\nchanged"));
        let r = apply(ws.path(), &plan(&items2, &clis), &clis, false).unwrap();
        assert!(r.conflicts.iter().any(|c| c.path.ends_with("conventional-commits.mdc") && c.reason == "edited"));
        assert_eq!(std::fs::read_to_string(&f).unwrap(), "my hand edit");
    }

    #[test]
    fn existing_user_file_is_not_overwritten() {
        let (_d, ws, items) = setup();
        std::fs::create_dir_all(ws.path().join(".cursor/rules")).unwrap();
        std::fs::write(ws.path().join(".cursor/rules/conventional-commits.mdc"), "mine").unwrap();
        let r = apply(ws.path(), &plan(&items, &["cursor"]), &["cursor"], false).unwrap();
        assert!(r.conflicts.iter().any(|c| c.reason == "exists"));
    }

    #[test]
    fn disabled_items_are_removed() {
        let (_d, ws, items) = setup();
        apply(ws.path(), &plan(&items, &["claude"]), &["claude"], false).unwrap();
        let only_rules: Vec<Item> = items.iter().filter(|i| i.kind == Kind::Rule).cloned().collect();
        let r = apply(ws.path(), &plan(&only_rules, &["claude"]), &["claude"], false).unwrap();
        assert!(r.removed.iter().any(|p| p.contains("test-writer")));
        assert!(!ws.path().join(".claude/agents").exists());
    }
}
